import{_ as a,o as n,c as o,a2 as t}from"./chunks/framework.CLyRW9b_.js";const p=JSON.parse('{"title":"Translations","description":"","frontmatter":{},"headers":[],"relativePath":"i18n/README.md","filePath":"i18n/README.md"}'),s={name:"i18n/README.md"};function r(i,e,l,d,c,h){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h1><p>Every word a person reads lives here, one JSON file per language and namespace (<a href="./../docs/adr/0014-text-lives-in-one-json-file-per-language-and-namespace">ADR 0014</a>, <a href="./../docs/adr/0015-catalog-text-lives-in-translation-files">ADR 0015</a>). English in <code>messages/en/</code> is the source.</p><ul><li><a href="https://github.com/tkint/coach-poulpy/tree/main/i18n/messages" target="_blank" rel="noreferrer"><code>messages/&lt;locale&gt;/&lt;namespace&gt;.json</code></a>: the messages, nested JSON whose path is the message id, in ICU MessageFormat.</li><li><code>project.inlang/settings.json</code>: the inlang project that <a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a> reads, through the next-intl plugin.</li><li><code>glossary/&lt;locale&gt;.md</code>: rules and vocabulary per language (<a href="./glossary/en">English</a>, <a href="./glossary/fr">français</a>); the English one also holds the translator notes.</li><li><code>typography.mjs</code>: fixes apostrophes, ellipses and each language’s non-breaking spaces; it runs on <code>main</code> after every merge.</li><li><code>key-map.json</code>: each Android and iOS string key from before the move, mapped to its message id, for switching the apps over (#99).</li></ul><h2 id="proofread-or-translate-in-fink" tabindex="-1">Proofread or translate in Fink <a class="header-anchor" href="#proofread-or-translate-in-fink" aria-label="Permalink to &quot;Proofread or translate in Fink&quot;">​</a></h2><ol><li>Open <a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a> and sign in with a free GitHub account.</li><li>Open the repository <code>tkint/coach-poulpy</code>; Fink finds <code>i18n/project.inlang</code>.</li><li>Pick the language, edit, and send the changes: Fink opens a pull request.</li></ol><p>Read the <a href="./glossary/en">English rules and notes</a> and the glossary of your language (<a href="./glossary/fr">français</a>) first. Type plain apostrophes and spaces: the repository fixes the typography after each merge.</p><h2 id="add-a-language" tabindex="-1">Add a language <a class="header-anchor" href="#add-a-language" aria-label="Permalink to &quot;Add a language&quot;">​</a></h2><p>Add its folder under <code>messages/</code> with the three files, its locale to <code>locales</code> in <code>project.inlang/settings.json</code>, and <code>glossary/&lt;locale&gt;.md</code>.</p>',8)])])}const f=a(s,[["render",r]]);export{p as __pageData,f as default};
